-- SNP Snapshot form (Settings > Content > Forms).
--
-- The SNP program's Snapshot step renders this form, editable: Trigger
-- Information, Member & Eligibility, Outreach & Engagement, Care Plan (ICP),
-- Transitions of Care (TOC) and Risk Stratification. Edit it in the Form
-- builder like any other form. Source: src/features/forms/templates/snpSnapshotForm.js
-- (scripts/seed.js upserts the same row). Answers are saved per patient
-- program in form_responses (session_id = 'snapshot:<patientId>:<programId>').
--
-- Guarded by name, so re-running never overwrites edits made in the builder.

INSERT INTO public.forms (name, description, category, form_type, status, schema, scoring, settings, response_count, updated_at)
SELECT
  'SNP Snapshot',
  'SNP program Snapshot: trigger, eligibility, outreach, care plan, transitions of care and risk stratification.',
  'Program',
  'Other',
  'active',
  '{"items":[{"linkId":"trigger","type":"group","text":"Trigger Information","columns":3,"items":[{"linkId":"trigger_type","type":"choice","control":"dropdown","text":"Trigger Type","readOnly":true,"options":[{"value":"HRA"},{"value":"Managed by HP"},{"value":"New Member"},{"value":"Reassessment"},{"value":"SCAN Trigger"},{"value":"SFTP Transfer"},{"value":"TOC"}]},{"linkId":"trigger_date","type":"date","text":"Trigger Date"},{"linkId":"first_outreach_due","type":"date","text":"First Outreach Due Date"},{"linkId":"icp_due","type":"date","text":"ICP Due Date"},{"linkId":"ict_due","type":"date","text":"ICT Due Date"},{"linkId":"managed_by_hp","type":"date","text":"Managed by HP"}]},{"linkId":"eligibility","type":"group","text":"Member & Eligibility","columns":3,"items":[{"linkId":"medicaid_id","type":"string","text":"Medicaid ID","placeholder":"Medicaid ID","readOnly":true},{"linkId":"health_plan","type":"string","text":"Health Plan Name","placeholder":"Health Plan Name","readOnly":true},{"linkId":"ppg_region","type":"string","text":"PPG Region Code","placeholder":"PPG Region Code","readOnly":true},{"linkId":"ipa","type":"string","text":"IPA","placeholder":"IPA","readOnly":true},{"linkId":"enrollment_date","type":"date","text":"Enrollment Date"},{"linkId":"termed_date","type":"date","text":"Termed Date"},{"linkId":"state_of_residence","type":"string","text":"State of Residence","placeholder":"State of Residence","readOnly":true},{"linkId":"dsnp_id","type":"string","text":"DSNP ID","placeholder":"DSNP ID","readOnly":true},{"linkId":"ppg_effective","type":"date","text":"PPG Effective Date"},{"linkId":"cm_assignment","type":"date","text":"Current CM Assignment Date"},{"linkId":"initial_hra","type":"date","text":"Initial HRA"},{"linkId":"latest_hra","type":"date","text":"Latest HRA"},{"linkId":"prior_year_hra","type":"date","text":"Prior Year HRA"}]},{"linkId":"outreach","type":"group","text":"Outreach & Engagement","columns":3,"items":[{"linkId":"first_call","type":"date","text":"First Initial Call"},{"linkId":"second_call","type":"date","text":"Second Call"},{"linkId":"last_utc","type":"date","text":"Last UTC Date and Time"},{"linkId":"ict_coordination_notes","type":"string","text":"Notes of ICT Coordination with Member","placeholder":"Notes of ICT Coordination with Member","readOnly":true}]},{"linkId":"care_plan","type":"group","text":"Care Plan (ICP)","columns":3,"items":[{"linkId":"initial_care_plan","type":"date","text":"Initial Care Plan Date"},{"linkId":"latest_care_plan","type":"date","text":"Latest Care Plan Date"},{"linkId":"icp_on_hra","type":"date","text":"ICP based on HRA (Latest Date)"},{"linkId":"icp_within_90","type":"choice","control":"radio","text":"ICP within 90 days","options":[{"value":"Yes"},{"value":"No"}]},{"linkId":"care_plan_type","type":"choice","control":"dropdown","text":"Care Plan Type","options":[{"value":"NA"},{"value":"Chronic Care Plan"},{"value":"Comprehensive Care Plan"},{"value":"Transition Care Plan"}]},{"linkId":"care_plan_to_pcp","type":"date","text":"Care Plan Sent to PCP"},{"linkId":"care_plan_to_member","type":"date","text":"Care Plan Shared With Member"}]},{"linkId":"toc","type":"group","text":"Transitions of Care (TOC)","columns":3,"items":[{"linkId":"toc_date","type":"date","text":"TOC Date"},{"linkId":"icp_after_toc","type":"date","text":"ICP Shared after TOC"},{"linkId":"toc_outreached","type":"choice","control":"radio","text":"TOC Outreached","options":[{"value":"Yes"},{"value":"No"}]},{"linkId":"toc_education","type":"choice","control":"radio","text":"TOC Education","options":[{"value":"Yes"},{"value":"No"}]},{"linkId":"toc_ict","type":"date","text":"TOC ICT"},{"linkId":"toc_icp_facility","type":"date","text":"TOC - ICP Shared with Facility"},{"linkId":"toc_icp_member","type":"date","text":"TOC - ICP Shared with Member/Main POC"},{"linkId":"initial_ict","type":"date","text":"Initial ICT"},{"linkId":"latest_ict","type":"date","text":"Latest ICT"}]},{"linkId":"risk","type":"group","text":"Risk Stratification","columns":3,"items":[{"linkId":"acuity_level","type":"choice","control":"dropdown","text":"Acuity Level","options":[{"value":"Low"},{"value":"Medium"},{"value":"High"},{"value":"Very High"}]},{"linkId":"risk_start","type":"date","text":"Risk Stratification Start Date"},{"linkId":"risk_end","type":"date","text":"Risk Stratification End Date"}]}]}'::jsonb,
  '{"scores":[],"criticalTriggers":[]}'::jsonb,
  '{"layout":"sectioned","header":{"enabled":true,"title":"SNP Snapshot"},"footer":{"enabled":false}}'::jsonb,
  0,
  now()
WHERE NOT EXISTS (SELECT 1 FROM public.forms WHERE name = 'SNP Snapshot');

